{
  "recipe_id": "dosa-batter-02",
  "title": "Crisp Dosa Batter",
  "ingredients": [
    {
      "name": "Dosa rice (raw, short-grain)",
      "amount": "750g"
    },
    {
      "name": "Whole white urad dal",
      "amount": "250g"
    },
    {
      "name": "Chana dal",
      "amount": "30g"
    },
    {
      "name": "Fenugreek seeds",
      "amount": "8g"
    },
    {
      "name": "Thick poha (flattened rice)",
      "amount": "50g"
    },
    {
      "name": "Fine sea salt",
      "amount": "18g"
    }
  ],
  "method": "Soak rice, urad dal, chana dal and fenugreek together for 5 hours; soak the\npoha separately for the last 30 minutes. Grind everything to a smooth, flowing\nbatter — thinner than idli batter — adding water a little at a time. Stir in\nthe salt and ferment 10 to 14 hours at 26–30°C until risen by half and sour-\nsmelling. Thin with water to pouring-cream consistency. Heat a cast-iron tawa\nuntil a water drop dances, wipe with an oiled onion half, pour a ladleful in\nthe centre and spiral outward with the ladle base to a thin, even round.\nDrizzle the edges with gingelly oil and cook until deep gold and crisp; a\nproper dosa releases itself from the pan."
}
